    public static void main(String[] args) {
        CDN cdn = new CDN();

        // Edge node E1's first request for this content: misses everywhere, fetches from origin.
        System.out.println("E1 requests 'video123': " + cdn.get("edge-1", "video123"));

        // E1 requests it again: now a fast edge hit.
        System.out.println("E1 requests 'video123' again: " + cdn.get("edge-1", "video123"));

        // A different edge node, E2, in the same region requests the same content for the first time.
        // It misses at its own edge, but hits the shared regional tier E1's earlier fetch already filled.
        System.out.println("E2 (different edge, same region) requests 'video123': " + cdn.get("edge-2", "video123"));

        // E2 requests it again: now a fast edge hit at E2 too.
        System.out.println("E2 requests 'video123' again: " + cdn.get("edge-2", "video123"));

        // The content is updated at origin, and purged across the whole hierarchy.
        cdn.purge("video123");

        // E1 requests it again after the purge: correctly misses everywhere and refetches from origin.
        System.out.println("E1 requests 'video123' after purge: " + cdn.get("edge-1", "video123"));
    }
}

// A multi-tier CDN: each edge node has its own local cache, all edge nodes in
// this simplified single-region demo share one regional cache tier, and a
// miss at both cascades all the way to origin, filling both tiers on the way back.
class CDN {
    private final Map<String, Map<String, String>> edgeCaches = new HashMap<>(); // edgeNodeId -> (key -> content)
    private final Map<String, String> regionalCache = new HashMap<>();               // shared across all edge nodes
    private final Map<String, String> origin = new HashMap<>();                         // the authoritative source

    CDN() {
        origin.put("video123", "original content v1");
    }

    // Returns both the content and which tier actually served it, to make the
    // cascading fill and cross-edge sharing behavior directly observable.
    String get(String edgeNodeId, String key) {
        Map<String, String> edgeCache = edgeCaches.computeIfAbsent(edgeNodeId, id -> new HashMap<>());

        if (edgeCache.containsKey(key)) {
            return edgeCache.get(key) + " [EDGE HIT]";
        }

        if (regionalCache.containsKey(key)) {
            String content = regionalCache.get(key);
            edgeCache.put(key, content); // fill this edge node's own cache for next time
            return content + " [REGIONAL HIT]";
        }

        String content = origin.get(key); // full miss: go all the way to origin
        regionalCache.put(key, content);      // fill the shared regional tier
        edgeCache.put(key, content);              // fill this edge node's own cache too
        return content + " [ORIGIN FETCH]";
    }

    // Invalidates a content key across the regional tier and every edge node's cache.
    void purge(String key) {
        regionalCache.remove(key);
        for (Map<String, String> edgeCache : edgeCaches.values()) {
            edgeCache.remove(key);
        }
    }
}

