#include <iostream>
#include <map>
#include <string>
using namespace std;

// A multi-tier CDN: each edge node has its own local cache, all edge nodes in
// this simplified single-region demo share one regional cache tier, and a
// miss at both cascades all the way to origin, filling both tiers on the way back.
class CDN {
public:
    CDN() {
        origin["video123"] = "original content v1";
    }

    string get(const string& edgeNodeId, const string& key) {
        map<string, string>& edgeCache = edgeCaches[edgeNodeId];

        if (edgeCache.count(key)) {
            return edgeCache[key] + " [EDGE HIT]";
        }

        if (regionalCache.count(key)) {
            string content = regionalCache[key];
            edgeCache[key] = content; // fill this edge node's own cache for next time
            return content + " [REGIONAL HIT]";
        }

        string content = origin[key]; // full miss: go all the way to origin
        regionalCache[key] = content;    // fill the shared regional tier
        edgeCache[key] = content;            // fill this edge node's own cache too
        return content + " [ORIGIN FETCH]";
    }

    void purge(const string& key) {
        regionalCache.erase(key);
        for (auto& entry : edgeCaches) {
            entry.second.erase(key);
        }
    }

private:
    map<string, map<string, string>> edgeCaches; // edgeNodeId -> (key -> content)
    map<string, string> regionalCache;               // shared across all edge nodes
    map<string, string> origin;                          // the authoritative source
};

int main() {
    CDN cdn;

    // Edge node E1's first request for this content: misses everywhere, fetches from origin.
    cout << "E1 requests 'video123': " << cdn.get("edge-1", "video123") << endl;

    // E1 requests it again: now a fast edge hit.
    cout << "E1 requests 'video123' again: " << cdn.get("edge-1", "video123") << endl;

    // A different edge node, E2, in the same region requests the same content for the first time.
    // It misses at its own edge, but hits the shared regional tier E1's earlier fetch already filled.
    cout << "E2 (different edge, same region) requests 'video123': " << cdn.get("edge-2", "video123") << endl;

    // E2 requests it again: now a fast edge hit at E2 too.
    cout << "E2 requests 'video123' again: " << cdn.get("edge-2", "video123") << endl;

    // The content is updated at origin, and purged across the whole hierarchy.
    cdn.purge("video123");

    // E1 requests it again after the purge: correctly misses everywhere and refetches from origin.
    cout << "E1 requests 'video123' after purge: " << cdn.get("edge-1", "video123") << endl;

    return 0;
}

